#include <stack>

void inOrderIterative(TreeNode* root) //栈的二叉树中序遍历
{
    stack<TreeNode*> s;
    TreeNode* current = root;

    while (!s.empty() || current != nullptr) {
        while (current != nullptr) {
            s.push(current);
            current = current->left;
        }

        current = s.top();
        s.pop();
        cout << current->value << " ";
        current = current->right;
    }
}

